"""P1 public official text only; no host facts in requests and no executable downloads."""
import concurrent.futures
import datetime
import hashlib
import html.parser
import json
from pathlib import Path
import urllib.request

R = Path(__file__).parent
URLS = {
    'studio-install': 'https://developer.android.com/studio/install',
    'emulator-acceleration': 'https://developer.android.com/studio/run/emulator-acceleration',
    'avd-management': 'https://developer.android.com/studio/run/managing-avds',
    'sdk-environment': 'https://developer.android.com/tools/variables',
    'windows-releases': 'https://learn.microsoft.com/en-us/windows/release-health/windows11-release-information',
    'hyperv-hardware': 'https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/host-hardware-requirements',
    'gradle-931-compatibility': 'https://docs.gradle.org/9.3.1/userguide/compatibility.html',
    'agp-910-release': 'https://developer.android.com/build/releases/agp-9-1-0-release-notes',
}
ALLOWED_HOSTS = {'developer.android.com', 'learn.microsoft.com', 'docs.gradle.org'}
class Redirects(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        from urllib.parse import urlsplit
        parsed = urlsplit(newurl)
        if parsed.scheme != 'https' or parsed.hostname not in ALLOWED_HOSTS:
            raise ValueError('Redirect outside official text-source allowlist')
        return super().redirect_request(req, fp, code, msg, headers, newurl)
class Text(html.parser.HTMLParser):
    def __init__(self):
        super().__init__(); self.skip = 0; self.parts = []
    def handle_starttag(self, tag, attrs):
        if tag in ('script', 'style'): self.skip += 1
    def handle_endtag(self, tag):
        if tag in ('script', 'style'): self.skip = max(0, self.skip - 1)
    def handle_data(self, data):
        if not self.skip and data.strip(): self.parts.append(data.strip())
def fetch(item):
    name, url = item
    record = {'id': name, 'url': url, 'requested_utc': datetime.datetime.now(datetime.timezone.utc).isoformat()}
    try:
        opener = urllib.request.build_opener(Redirects())
        req = urllib.request.Request(url, headers={'User-Agent': 'YourOwn-static-review/1.0', 'Accept': 'text/html,text/plain;q=0.9', 'Accept-Encoding': 'identity'})
        with opener.open(req, timeout=30) as res:
            kind = res.headers.get('Content-Type', '')
            if not (kind.startswith('text/html') or kind.startswith('text/plain')):
                raise ValueError('Unexpected non-text response type: ' + kind)
            raw = res.read(4_000_001)
            if len(raw) > 4_000_000: raise ValueError('Four-million-byte response limit exceeded')
            record.update(status=res.status, final_url=res.url, content_type=kind, bytes=len(raw), sha256=hashlib.sha256(raw).hexdigest())
        with (R / (name + '.raw')).open('xb') as f: f.write(raw)
        parser = Text(); parser.feed(raw.decode('utf-8'))
        txt = '\n'.join(parser.parts) + '\n'
        with (R / (name + '.txt')).open('x', encoding='utf-8', newline='\n') as f: f.write(txt)
        record['text_sha256'] = hashlib.sha256(txt.encode('utf-8')).hexdigest()
    except Exception as exc:
        record['error'] = repr(exc)
    return record
assert not (R / 'sources.json').exists(), 'Preserve the first attempt; no implicit retries'
with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool:
    records = list(pool.map(fetch, URLS.items()))
with (R / 'sources.json').open('x', encoding='utf-8', newline='\n') as f:
    json.dump(records, f, indent=2); f.write('\n')
for r in records: print(r['id'], r.get('status'), r.get('bytes'), r.get('error', ''))
